// map-picker.component.ts using MapLibre GL
import { Component, OnInit } from '@angular/core';
import * as maplibregl from 'maplibre-gl';
import { Router } from '@angular/router';

@Component({
  selector: 'app-map-picker',
  templateUrl: './map-picker.component.html',
  styleUrls: ['./map-picker.component.css']
})
export class MapPickerComponent implements OnInit {
  map: any;
  marker: any;

  constructor(private router: Router) { }

  ngOnInit(): void {
    this.loadMap();
  }

  loadMap(): void {
    this.map = new maplibregl.Map({
      container: 'map',
      style: 'https://demotiles.maplibre.org/style.json',
      center: [78.486671, 17.385044], // [lng, lat]
      zoom: 13
    });

    this.map.on('click', (e: any) => {
      const lng = e.lngLat.lng;
      const lat = e.lngLat.lat;

      if (this.marker) {
        this.marker.remove();
      }

      this.marker = new maplibregl.Marker()
        .setLngLat([lng, lat])
        .addTo(this.map);

      localStorage.setItem('selectedLat', lat.toString());
      localStorage.setItem('selectedLng', lng.toString());

      this.router.navigate(['/add-shops']);
    });
  }
}
<div class="map-container">
  <div id="map"></div>
  <button class="confirm-btn" (click)="confirmLocation()">Confirm Location</button>
</div>
